export const ICON_BY_ID = new Map(ICON_GROUPS.flatMap((g) => g.items).map((i) => [i.id, i]))

/** Значение поля icon — иконка из каталога, а не старое эмодзи. */
export const isCatalogIcon = (v: string | undefined): boolean => !!v && ICON_BY_ID.has(v)
